#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}

    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }

    void eat() {
        fish = fish + 1;
        cout << name << " 吃掉了一条" << endl;
    }
};

int main() {
    int a = 0;
    int b = 0;
    cin >> a >> b;

    Cat c1("小橘", a);
    c1.show();
    c1.eat();
    c1.show();

    const Cat c2("狸花", b);
    c2.show();
    return 0;
}

